(* The instantiation manager (ADR-0012 §1.2/§1.4/§1.5). Tranche 1: store + frame-scoped
   liveness/dedup + a manual seed queue + the budget-bounded [round] that drains it. The
   matcher (tranche 2) replaces the seed producer; everything else here is durable. *)

open Oxsmt_core
module Sat = Oxsmt_solver.Sat

let default_gen_budget = 100_000

(* Chunk 3 (MBQI-lite seeding) knobs. A lemma whose triggers are ground-less — the inert
   2b Skolem-function population — never E-matches; [round] then seeds it with existing
   ground terms of each qvar's sort, budget-capped. [pool_cap] bounds each qvar's
   candidate pool (first N by registration id); [seed_cap] bounds the NEW seed instances
   emitted per lemma per [check_sat]; [seed_enum_ceiling] bounds the tuples the odometer
   enumerates per lemma per round (so a many-qvar cross-product cannot spin). All three
   are deterministic and are additionally clamped by the shared generation budget. *)
let default_seed_cap = 32
let default_pool_cap = 16
let seed_enum_ceiling = 512

(* Model-guided instantiation (quant-mgi, dark OXSMT_EMATCH_MGI). Once a [check_sat] has
   spent at least [default_mgi_threshold] generation steps with a live lemma — i.e. it is
   FLOODING toward the [lemma-gen-budget] Unknown — the round stops emitting matcher
   instances whose ground body is ALREADY SATISFIED by the current model (pure churn the
   SAT/theory solver will not act on), keeping only the model-falsified (conflict) and
   model-undetermined (novel / reachability) ones. Below the threshold the round is
   byte-identical to legacy, so a file that refutes quickly never engages the filter
   (respecting the trajectory-fragility law). Calibrated to 100k = 10% of the 1M budget
   floor: engaging earlier (measured at 5k) diverts files that refute in the 100k..1M step
   range (4 deterministic board regressions); at 100k those clear (0 deterministic
   regressions) while the deep floods — which spend the full 1M — still cross it and get the
   filter for the remaining ~900k. *)
let default_mgi_threshold = 100_000

type stats =
  { live_lemmas : int
  ; instances : int
  ; rounds : int
  ; seeds : int
  (* NEW ground instances generated by seeding (chunk 3), session-cumulative *)
  }

(* Provenance of one generated ground instance (ADR-0012: "each instantiation records
   which lemma and which substitution produced it, and replays in the certificate
   checker"). Certificate replay of instantiations is a later tranche, but the RECORD
   exists now: an append-only log of every NEW instance actually handed to the session to
   assert. A budget-aborted round's instances are rolled OUT of the log (they are never
   asserted), so the log is exactly the asserted-instance sequence. *)
type instantiation =
  { lemma_id : int (* the source lemma's dense id ({!Lemma.t.id}) *)
  ; subst : Term.t array (* ground image of each qvar, in [Lemma.qvars] order *)
  ; instance : Term.t (* the resulting ground body [φ[σ]] *)
  }

type t =
  { ctx : Context.t
  ; env : Env.t
  ; gen_budget : int
  ; streaming_partial : bool
      (* Default-off experiment: stream matches and retain the sound prefix on budget
         exhaustion instead of transactionally discarding the entire round. *)
  ; fair_slices : bool
      (* Default-off experiment: bound each lemma's share of one matching pass so a
         prolific early lemma cannot starve every later lemma. Implies streaming. *)
  ; seed_enabled : bool (* chunk 3: seeding on (default); the OFF mutant is the RED *)
  ; model_guided : bool (* quant-mgi: model-guided flood filter (dark OXSMT_EMATCH_MGI) *)
  ; mgi_threshold : int (* generation steps this check before the MGI filter engages *)
  ; seed_cap : int (* NEW seed instances per lemma per [check_sat] *)
  ; pool_cap : int (* candidate ground terms per qvar sort *)
  ; seeded : (int, int) Hashtbl.t
      (* lemma id -> NEW seed instances emitted this check (per-lemma seed cap gate);
         reset by [begin_check]. *)
  ; mutable total_seeds : int (* session-cumulative NEW seed instances (stats) *)
  ; mutable next_id : int
  ; mutable lemmas : Lemma.t list (* the live store; a pop filters it (§1.5) *)
  ; seeds : (Lemma.t * Term.t array) Queue.t (* tranche-1 manual instances *)
  ; dedup : (Sat.var * int, unit) Hashtbl.t
      (* (owning frame selector, instance body tag) -> present. Keyed on (frame, tag), NOT
         tag alone (codex M1): the SAME body guarded by two different selectors is two
         DIFFERENT clauses, so two live lemmas' equal-bodied instances must NOT dedup each
         other. Scoped to active-clause lifetime — dropped on that frame's pop (§1.4 R2). *)
  ; mutable budget_remaining : int
  ; mutable budget_hit : bool
  ; mutable total_instances : int
  ; mutable total_rounds : int
  ; mutable provenance : instantiation list (* newest-first; see {!instantiation} *)
  }

let create
  ?(gen_budget = default_gen_budget)
  ?(seed = true)
  ?(model_guided = false)
  ?(mgi_threshold = default_mgi_threshold)
  ?(seed_cap = default_seed_cap)
  ?(pool_cap = default_pool_cap)
  ?streaming_partial:streaming_override
  ?fair_slices:fair_override
  ctx
  env
  =
  let stream_requested =
    match streaming_override with
    | Some value -> value
    | None ->
      (match Sys.getenv_opt "OXSMT_LEMMA_STREAM" with
       | Some ("1" | "true" | "yes") -> true
       | Some _ | None -> false)
  in
  let fair_slices =
    match fair_override with
    | Some value -> value
    | None ->
      (* DEFAULT-ON flip (LAND 45 reviewed +255 lever: full board 2912->3171, 18:1
         win:regr, 0 soundness). Unset => ON. The opt-out tokens [0/false/no] plus any
         UNRECOGNIZED value => OFF: [OXSMT_LEMMA_FAIR=0] byte-recovers the pre-flip trunk,
         and a typo cannot silently turn a reviewed lever on/off surprisingly.
         Garbage=>OFF is the conservative side, matching the [OXSMT_LRA] flip lever this
         mirrors. FAIR implies streaming
         ([streaming_partial = stream_requested || fair_slices]), so the whole reviewed
         mechanism turns on together. *)
      (match Sys.getenv_opt "OXSMT_LEMMA_FAIR" with
       | Some ("1" | "true" | "yes") -> true
       | Some _ -> false
       | None -> true)
  in
  let streaming_partial = stream_requested || fair_slices in
  { ctx
  ; env
  ; gen_budget
  ; streaming_partial
  ; fair_slices
  ; seed_enabled = seed
  ; model_guided
  ; mgi_threshold
  ; seed_cap
  ; pool_cap
  ; seeded = Hashtbl.create 16
  ; total_seeds = 0
  ; next_id = 0
  ; lemmas = []
  ; seeds = Queue.create ()
  ; dedup = Hashtbl.create 64
  ; budget_remaining = gen_budget
  ; budget_hit = false
  ; total_instances = 0
  ; total_rounds = 0
  ; provenance = []
  }
;;

let context t = t.ctx
let env t = t.env

let fresh_id t =
  let id = t.next_id in
  t.next_id <- t.next_id + 1;
  id
;;

let add_lemma t (lemma : Lemma.t) = t.lemmas <- lemma :: t.lemmas
let has_live_lemma t = t.lemmas <> []

(* codex C2: only a lemma PHYSICALLY present in this manager's live store may be seeded.
   [List.memq] closes ownership AND liveness in one check: a handle from a different
   session is not in this manager's store (its base selector would otherwise collide,
   riding an active foreign selector -> wrong Unsat); a popped lemma was filtered out of
   the store by [on_pop]. Reject a foreign/stale handle rather than enqueue it. *)
let seed_instance t lemma sigma =
  if not (List.memq lemma t.lemmas)
  then
    invalid_arg
      "Ematch.Manager.seed_instance: lemma handle is not a live lemma of this session \
       (foreign or popped)";
  Queue.add (lemma, sigma) t.seeds
;;

let begin_check t =
  t.budget_remaining <- t.gen_budget;
  t.budget_hit <- false;
  (* per-lemma seed cap is per [check_sat] (§chunk 3): a fresh budget each check *)
  Hashtbl.reset t.seeded
;;

let budget_exhausted t = t.budget_hit
let retains_partial_batch t = t.streaming_partial

(* Debit one generation-budget step; raise [Matcher.Budget_exhausted] the instant the
   budget is spent (R4). Shared with the matcher (which debits its own enumeration steps
   against the same [budget] ref); [round] catches the exception and degrades to
   [unknown]. *)
let spend budget =
  if !budget <= 0 then raise Matcher.Budget_exhausted;
  decr budget
;;

(* MBQI-lite seeding (chunk 3). For a live lemma whose triggers are ground-less — the
   inert 2b Skolem-function population, which E-matching NEVER fires — enumerate ground
   substitutions from the existing e-graph: for each qvar, the registered ground terms of
   its sort (first [pool_cap] by id), crossed as a deterministic mixed-radix odometer
   (last qvar fastest), returning at most [max_tuples] tuples. Every instance is a ground
   consequence of the (universally valid) lemma, so seeding is universally SOUND — the
   only risks are budget (bounded here + by the shared generation budget) and
   completeness- theater (measured on the board). A qvar with no ground term of its sort
   yields no tuple at all (a sound miss, never a wrong instance). [] for a zero-qvar
   lemma: its body is a ground fact the matcher already emits once, so seeding it would
   only duplicate. *)
let seed_substitutions view (lemma : Lemma.t) ~pool_cap ~max_tuples =
  let qvars = lemma.Lemma.qvars in
  let k = Array.length qvars in
  if k = 0
  then []
  else (
    let take n l =
      let rec go n = function
        | x :: tl when n > 0 -> x :: go (n - 1) tl
        | _ -> []
      in
      go n l
    in
    let pools =
      Array.map
        (fun q ->
          let sort = (Qvar.to_term q).Term.sort in
          Array.of_list (take pool_cap (view.Egraph_view.ground_terms_by_sort sort)))
        qvars
    in
    if Array.exists (fun p -> Array.length p = 0) pools
    then []
    else (
      let out = ref [] in
      let count = ref 0 in
      let idx = Array.make k 0 in
      let continue = ref true in
      while !continue && !count < max_tuples do
        out := Array.init k (fun j -> pools.(j).(idx.(j))) :: !out;
        incr count;
        (* increment the mixed-radix odometer from the last position *)
        let j = ref (k - 1) in
        let carry = ref true in
        while !carry && !j >= 0 do
          idx.(!j) <- idx.(!j) + 1;
          if idx.(!j) >= Array.length pools.(!j)
          then (
            idx.(!j) <- 0;
            decr j)
          else carry := false
        done;
        if !carry then continue := false (* wrapped: cross-product exhausted *)
      done;
      List.rev !out))
;;

(* Three-valued (Kleene) evaluation of a ground instance body under the CURRENT MODEL
   (quant-mgi). Leaf atoms ([Eq]/[Le]/Bool-sorted [App]/[Bool_const]) are read from
   [view.atom_value] (the SAT solver's saved assignment; [None] for a NEW atom this
   instance introduces). Connectives combine 3-valued: [And]/[Or] short-circuit on a
   determining child, [Ite] follows a determined condition else joins the branches.
   [Some true] only when the WHOLE body is determined satisfied, [Some false] when
   determined violated, [None] when any needed atom is unknown. Used ONLY to DROP
   model-satisfied churn during a flood; a [None]/wrong answer keeps the instance, so it
   can never suppress a refutation instance (selection-only, sound). *)
let rec eval_under_model view (term : Term.t) : bool option =
  match term.node with
  | Bool_const b -> Some b
  | Not a -> Option.map not (eval_under_model view a)
  | And xs ->
    let vs = List.map (eval_under_model view) (Iarr.to_list xs) in
    if List.exists (fun v -> v = Some false) vs
    then Some false
    else if List.for_all (fun v -> v = Some true) vs
    then Some true
    else None
  | Or xs ->
    let vs = List.map (eval_under_model view) (Iarr.to_list xs) in
    if List.exists (fun v -> v = Some true) vs
    then Some true
    else if List.for_all (fun v -> v = Some false) vs
    then Some false
    else None
  | Ite (c, a, b) ->
    (match eval_under_model view c with
     | Some true -> eval_under_model view a
     | Some false -> eval_under_model view b
     | None ->
       let va = eval_under_model view a
       and vb = eval_under_model view b in
       if va = vb then va else None)
  | Eq _ | Le _ -> view.Egraph_view.atom_value term
  | App (_, _) when Sort.equal term.sort Sort.bool -> view.Egraph_view.atom_value term
  | App _ | Int_const _ | Real_const _ | Arith _ | Real_arith _ -> None
;;

(* Produce the next batch of ground instances (ADR-0012 §1.4, tranche 2). Two producers
   feed ONE dedup + budget + assert pipeline:
   1. the E-matcher ({!Matcher.substitutions}) over every live lemma, in deterministic
      lemma-id order (R8 round-robin fairness is tranche 3); and
   2. the tranche-1 manual seed queue ({!seed_instance}), still supported so the manual
      path and its honeypots keep working — a seeded instance the matcher also finds
      dedups. The generation budget is debited INSIDE the matcher's enumeration (R4) and
      once per NEW emitted instance / drained seed; on exhaustion the whole round stops
      with instances still pending, and the loop degrades to [unknown] this check.
      Deterministic order (matcher output, then seed FIFO order; I6). *)
let round t view =
  t.total_rounds <- t.total_rounds + 1;
  let out = ref [] in
  let budget = ref t.budget_remaining in
  (* Keys this round added to [dedup], newest-first — so an aborted round can roll them
     back (codex MED, manager.ml dedup pollution): the session asserts the WHOLE batch
     [out] only when the round did NOT hit the budget; on [budget_exhausted] it discards
     [out] and returns [Unknown] WITHOUT asserting (session.ml). If the dedup entries
     survived, those never-asserted instances would be permanently suppressed on a later
     round -> a missed refutation (spurious [Unknown] where [Unsat] is right). So a dedup
     entry must only outlive the round if its instance is actually handed to the session
     to assert. *)
  let added = ref [] in
  (* Manual seeds popped this round, newest-first — restored to the queue on abort so a
     seed consumed by an aborted round is NOT lost (codex: the popped-seeds sibling of the
     dedup-pollution path). The whole round is transactional: on [Budget_exhausted] the
     session discards the batch, so both the dedup entries AND the consumed seeds roll
     back to their pre-round state. *)
  let consumed_seeds = ref [] in
  (* NEW seed instances (chunk 3) emitted this round — rolled out of [total_seeds] on
     abort (like [added] for [total_instances]), so the stat tracks only asserted seed
     instances. *)
  let seeds_this_round = ref 0 in
  (* Model-guided flood filter (quant-mgi): engages once this [check_sat] has spent at
     least [mgi_threshold] generation steps with a live lemma (flooding toward the
     [lemma-gen-budget] Unknown). Computed once per round from the budget spent BEFORE
     this round, so a check byte-identically follows legacy until it floods. *)
  let mgi_filtering =
    t.model_guided && t.gen_budget - t.budget_remaining >= t.mgi_threshold
  in
  (* Turn a (lemma, sigma) into a deduped, budget-debited instance. Dedup is keyed
     (owning-frame selector, instance body tag): a duplicate (already-active clause) costs
     no budget and emits nothing (redundancy filter, §L5). [~filter] applies the
     model-guided drop (matcher phase only): during a flood, an instance whose ground body
     is ALREADY SATISFIED by the current model is churn the solver will not act on, so it
     is skipped (not deduped — re-evaluated next round in case the model changes).
     Selection-only: a model-falsified or model-undetermined instance is always kept. *)
  (* [true] iff this call EMITTED a new instance (dedup miss); [false] on a dedup hit. The
     seeding producer uses the result to charge its per-lemma seed cap only on real
     emissions (a re-seeded duplicate costs nothing and must not consume the cap). *)
  let process ?(filter = false) debit (lemma : Lemma.t) sigma =
    let inst = Instance.of_subst t.ctx ~qvars:lemma.qvars ~body:lemma.body sigma in
    let key = lemma.frame, (Instance.to_term inst).Term.tag in
    if Hashtbl.mem t.dedup key
    then false
    else if filter && eval_under_model view (Instance.to_term inst) = Some true
    then false (* model already satisfies this instance: skip the churn (quant-mgi) *)
    else (
      spend debit;
      Hashtbl.replace t.dedup key ();
      added := key :: !added;
      t.total_instances <- t.total_instances + 1;
      (* Provenance: one record per NEW instance, in lockstep with the dedup key. A
         budget-aborted round drops exactly [List.length !added] newest records below, so
         the log tracks the asserted-instance sequence (never a never-asserted instance). *)
      t.provenance
      <- { lemma_id = lemma.Lemma.id; subst = sigma; instance = Instance.to_term inst }
         :: t.provenance;
      out := (lemma.frame, inst) :: !out;
      true)
  in
  (try
     (* [t.lemmas] is newest-first (add_lemma prepends); [List.rev] gives ascending id
        order — deterministic. Each live lemma is matched against the read-only e-graph
        view. *)
     let ascending = List.rev t.lemmas in
     (* Phase 1: E-matching over every live lemma. Track (a) whether ANY new instance was
        emitted this round from the matcher, and (b) the lemmas the matcher found nothing
        for (subs = [] — trigger-inert, the seed candidates). *)
     let matcher_emitted = ref 0 in
     let inert = ref [] in
     let fair_exhausted = ref false in
     let lemma_count = max 1 (List.length ascending) in
     List.iter
       (fun (lemma : Lemma.t) ->
         if t.fair_slices
         then (
           (* Spend at most one deterministic slice on this lemma. Enumeration and new
              instance emission share the slice, exactly as they share the legacy global
              budget. Charge the used slice back to the global per-check balance. *)
           let quota = max 64 (min 4096 (t.gen_budget / lemma_count)) in
           let initial = min quota !budget in
           let local = ref initial in
           let matched = ref false in
           (try
              Matcher.iter_substitutions view lemma ~budget:local ~yield:(fun sigma ->
                matched := true;
                if process ~filter:mgi_filtering local lemma sigma then incr matcher_emitted)
            with
            | Matcher.Budget_exhausted -> fair_exhausted := true);
           budget := !budget - (initial - !local);
           if not !matched then inert := lemma :: !inert)
         else if t.streaming_partial
         then (
           let matched = ref false in
           Matcher.iter_substitutions view lemma ~budget ~yield:(fun sigma ->
             matched := true;
             if process ~filter:mgi_filtering budget lemma sigma then incr matcher_emitted);
           if not !matched then inert := lemma :: !inert)
         else (
           let subs = Matcher.substitutions view lemma ~budget in
           List.iter
             (fun sigma ->
               if process ~filter:mgi_filtering budget lemma sigma then incr matcher_emitted)
             subs;
           if subs = [] then inert := lemma :: !inert))
       ascending;
     (* Phase 2 (chunk 3, MBQI-lite): seed ONLY when E-matching has GLOBALLY saturated
        this round ([matcher_emitted = 0]) — the charter's "when E-matching saturates"
        trigger. Seeding while the matcher is still productive (some other lemma
        advancing) is pure churn that competes for the generation budget and, empirically,
        degrades previously-solved files to [unknown] (the −60 UFDT regression of the
        per-lemma variant). Gating on global saturation confines seeding to the
        genuinely-stuck rounds: the trigger-inert lemmas get ground seeds only as a last
        resort before the loop would otherwise degrade to [unknown]. Seeds are capped
        [seed_cap] NEW instances per lemma per check and feed the same dedup+budget+assert
        pipeline. *)
     if t.seed_enabled && !matcher_emitted = 0 && not !fair_exhausted
     then
       List.iter
         (fun (lemma : Lemma.t) ->
           let emitted () =
             Option.value (Hashtbl.find_opt t.seeded lemma.Lemma.id) ~default:0
           in
           if emitted () < t.seed_cap
           then
             List.iter
               (fun sigma ->
                 if emitted () < t.seed_cap && process budget lemma sigma
                 then (
                   Hashtbl.replace t.seeded lemma.Lemma.id (emitted () + 1);
                   t.total_seeds <- t.total_seeds + 1;
                   incr seeds_this_round))
               (seed_substitutions
                  view
                  lemma
                  ~pool_cap:t.pool_cap
                  ~max_tuples:seed_enum_ceiling))
         (List.rev !inert);
     (* Drain the manual seed queue (tranche-1 scaffold). Record each popped seed BEFORE
        processing so an abort mid-drain can restore the ones this round consumed. *)
     while not (Queue.is_empty t.seeds) do
       let seed = Queue.pop t.seeds in
       consumed_seeds := seed :: !consumed_seeds;
       let lemma, sigma = seed in
       ignore (process budget lemma sigma : bool)
     done;
     if !fair_exhausted then t.budget_hit <- true
   with
   | Matcher.Budget_exhausted ->
     t.budget_hit <- true;
     if not t.streaming_partial
     then (
       (* Legacy all-or-nothing transaction: OFF stays byte-identical. *)
       List.iter (Hashtbl.remove t.dedup) !added;
       t.total_instances <- t.total_instances - List.length !added;
       t.total_seeds <- t.total_seeds - !seeds_this_round;
       let rec drop n l =
         if n <= 0
         then l
         else (
           match l with
           | [] -> []
           | _ :: tl -> drop (n - 1) tl)
       in
       t.provenance <- drop (List.length !added) t.provenance;
       out := []);
     (* Restore the seeds this aborted round consumed, at the FRONT of the queue in
        original FIFO order (the not-yet-consumed remainder stays after them), so no
        manual seed is dropped by an aborted round. *)
     (match !consumed_seeds with
      | [] -> ()
      | _ :: _ ->
        let restored = Queue.create () in
        List.iter (fun s -> Queue.add s restored) (List.rev !consumed_seeds);
        Queue.transfer t.seeds restored;
        Queue.transfer restored t.seeds));
  t.budget_remaining <- !budget;
  List.rev !out
;;

let on_pop t selector =
  t.lemmas <- List.filter (fun (l : Lemma.t) -> not (Int.equal l.frame selector)) t.lemmas;
  (* drop dedup entries owned by the popped frame (§1.4 R2: retracted instance
     re-generates) — the key is (frame, tag), so match on the frame component *)
  let stale =
    Hashtbl.fold
      (fun ((fr, _tag) as key) () acc ->
        if Int.equal fr selector then key :: acc else acc)
      t.dedup
      []
  in
  List.iter (Hashtbl.remove t.dedup) stale;
  (* drop pending seeds whose lemma lived in the popped frame *)
  let kept = Queue.create () in
  Queue.iter
    (fun ((l, _) as s) -> if not (Int.equal l.Lemma.frame selector) then Queue.add s kept)
    t.seeds;
  Queue.clear t.seeds;
  Queue.transfer kept t.seeds
;;

(* The instantiation provenance, oldest-first (generation order). [t.provenance] is stored
   newest-first, so reverse. A pop does NOT prune this: it is a HISTORICAL trace of what
   was instantiated (the soundness of a popped instance is handled by its deactivated
   frame selector, not by this record); frame-scoped pruning for replay is a
   certificate-tranche concern. *)
let instantiations t = List.rev t.provenance

let stats t =
  { live_lemmas = List.length t.lemmas
  ; instances = t.total_instances
  ; rounds = t.total_rounds
  ; seeds = t.total_seeds
  }
;;
